/**
 * emit to subscription queries of type FindTrainingCourse,
 * but only if the id matches
 *
 * @param		entity	TrainingCourse
 */
	protected void emitFindTrainingCourse( TrainingCourse entity ) {
		LOGGER.info("handling emitFindTrainingCourse" );
		
	    queryUpdateEmitter.emit(FindTrainingCourseQuery.class,
	                            query -> query.getFilter().getTrainingCourseId().equals(entity.getTrainingCourseId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllTrainingCourse
	 * 
	 * @param		entity	TrainingCourse
	 */
	protected void emitFindAllTrainingCourse( TrainingCourse entity ) {
		LOGGER.info("handling emitFindAllTrainingCourse" );
		
	    queryUpdateEmitter.emit(FindAllTrainingCourseQuery.class,
	                            query -> true,
	                            entity);
	}

